package ama.transcript;
import ama.contract.MinutesContracts.*;import ama.minutes.contract.*;import java.util.*;
import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Complete detached stored-result shape and represented original-source validation. */
final class MinutesStoredResults {
 static List<EvidenceAnchor> anchors(MinutesGraphCapture.Graph graph,TranscriptAcquisitionBudget.Ledger budget){
  var result=new ArrayList<EvidenceAnchor>();var reader=new ama.minutes.json.StoredMinutesAnchorReader();for(var evidence:JdbcMinutesFactsReader.rows(graph,Table.EVIDENCE_LINK)){budget.check();String element=evidence.nullableString("element_id"),body=evidence.nullableString("minutes_revision_id");require((element==null)!=(body==null),PROVENANCE_UNAVAILABLE);var target=JdbcMinutesFactsReader.one(graph,element==null?Table.MINUTES_REVISION:Table.MINUTES_ELEMENT,element==null?body:element);var anchor=reader.read(evidence.string("target_anchor"),()->false);require(anchor.equals(OutputValidation.anchor(target.string("body"),anchor.start(),anchor.end(),()->false)),PROVENANCE_UNAVAILABLE);result.add(new EvidenceAnchor(evidence.string("id"),anchor));}return List.copyOf(result);
 }
 static void validate(MinutesGraphCapture.Graph graph,StoredProvenanceFacts facts,GraphBudget graphBudget,TranscriptAcquisitionBudget.Ledger budget){
  String meeting=graph.discovery().meeting();var sourceGraph=new StoredSourceGraph();
  for(var body:JdbcMinutesFactsReader.rows(graph,Table.MINUTES_REVISION)){
   budget.check();require(meeting.equals(body.string("meeting_id"))&&body.number("revision")>0,PROVENANCE_UNAVAILABLE);String parent=body.nullableString("parent_id"),input=body.nullableString("generation_input_id");if(parent!=null){var prior=JdbcMinutesFactsReader.one(graph,Table.MINUTES_REVISION,parent);require(meeting.equals(prior.string("meeting_id"))&&prior.number("revision")<body.number("revision"),PROVENANCE_UNAVAILABLE);}if(input!=null)require(meeting.equals(JdbcMinutesFactsReader.one(graph,Table.GENERATION_INPUT,input).string("meeting_id")),PROVENANCE_UNAVAILABLE);if("AI".equals(body.string("title_origin")))require(input!=null,PROVENANCE_UNAVAILABLE);sourceGraph.derive(facts,new GraphSelection(meeting,body.string("id"),null,null,null),graphBudget,()->false);
  }
  for(var set:JdbcMinutesFactsReader.rows(graph,Table.ELEMENT_SET)){
   budget.check();String id=set.string("id");require(meeting.equals(set.string("meeting_id"))&&set.number("revision")>0,PROVENANCE_UNAVAILABLE);var elements=JdbcMinutesFactsReader.rows(graph,Table.MINUTES_ELEMENT).stream().filter(r->id.equals(r.string("set_id"))).toList();for(Category category:Category.values())ordinals(elements.stream().filter(r->category.name().equals(r.string("category"))).toList());
   for(var element:elements){String key=element.string("id");var accepted=JdbcMinutesFactsReader.rows(graph,Table.ACTION_ITEM).stream().filter(r->key.equals(r.string("element_id"))).toList();var suggested=JdbcMinutesFactsReader.rows(graph,Table.ACTION_SUGGESTION).stream().filter(r->key.equals(r.string("element_id"))).toList();require(element.string("category").equals("ACTION")?accepted.size()==1&&suggested.size()<=1:accepted.isEmpty()&&suggested.isEmpty(),PROVENANCE_UNAVAILABLE);}
   for(SensitiveKind category:SensitiveKind.values())ordinals(JdbcMinutesFactsReader.rows(graph,Table.SENSITIVE_DETECTION).stream().filter(r->id.equals(r.string("set_id"))&&category.name().equals(r.string("category"))).toList());ordinals(JdbcMinutesFactsReader.rows(graph,Table.BACKGROUND_NOTE).stream().filter(r->id.equals(r.string("set_id"))).toList());sourceGraph.derive(facts,new GraphSelection(meeting,null,id,null,null),graphBudget,()->false);
  }
  for(var candidate:graph.auxiliary().getOrDefault("generation_candidate",List.of())){
   budget.check();String id=(String)candidate.get("id"),inputId=(String)candidate.get("input_id"),taskId=(String)candidate.get("task_id"),bodyId=(String)candidate.get("minutes_revision_id"),setId=(String)candidate.get("element_set_id");require(meeting.equals(candidate.get("meeting_id"))&&bodyId!=null&&setId!=null,PROVENANCE_UNAVAILABLE);var input=JdbcMinutesFactsReader.one(graph,Table.GENERATION_INPUT,inputId);var body=JdbcMinutesFactsReader.one(graph,Table.MINUTES_REVISION,bodyId);var set=JdbcMinutesFactsReader.one(graph,Table.ELEMENT_SET,setId);require(inputId.equals(body.nullableString("generation_input_id"))&&"AI".equals(body.string("title_origin"))&&meeting.equals(set.string("meeting_id"))&&body.string("created_by").equals(graph.discovery().root().get("owner_id"))&&input.number("base_revision")==((Number)candidate.get("base_revision")).longValue()&&input.string("input_fingerprint").equals(candidate.get("input_fingerprint")),PROVENANCE_UNAVAILABLE);
   var tasks=graph.auxiliary().getOrDefault("durable_task",List.of()).stream().filter(t->taskId.equals(t.get("id"))).toList();require(tasks.size()==1,PROVENANCE_UNAVAILABLE);var task=tasks.getFirst();require("GENERATION_INPUT".equals(task.get("input_kind"))&&inputId.equals(task.get("input_id"))&&Set.of("SUCCEEDED","STALE").contains(task.get("state")),PROVENANCE_UNAVAILABLE);String state=(String)candidate.get("state");require(Set.of("PENDING","ADOPTED","STALE").contains(state),PROVENANCE_UNAVAILABLE);if(!state.equals("STALE")||task.get("state").equals("SUCCEEDED"))require("SUCCEEDED".equals(task.get("state"))&&"GENERATION_CANDIDATE".equals(task.get("output_kind"))&&id.equals(task.get("output_id")),PROVENANCE_UNAVAILABLE);else require(task.get("output_kind")==null&&task.get("output_id")==null&&"BUSINESS_FENCED".equals(task.get("last_error")),PROVENANCE_UNAVAILABLE);
   var executions=graph.auxiliary().getOrDefault("external_execution",List.of()).stream().filter(e->taskId.equals(e.get("task_id"))).toList();require(executions.size()==1&&"SUCCEEDED".equals(executions.getFirst().get("state"))&&((Number)executions.getFirst().get("execution_no")).longValue()==1,PROVENANCE_UNAVAILABLE);
  }
 }
 private static void ordinals(List<FullRow> rows){long expected=1;for(var row:rows.stream().sorted(Comparator.comparingLong(r->r.number("ordinal"))).toList())require(row.number("ordinal")==expected++,PROVENANCE_UNAVAILABLE);}
}
